PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS accounts(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, salt TEXT NOT NULL, password_hash TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY, account_id TEXT, role TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS sessions_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY, name TEXT NOT NULL, invite_hash TEXT UNIQUE NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS children(id TEXT PRIMARY KEY, parent_id TEXT NOT NULL REFERENCES accounts(id), group_id TEXT NOT NULL REFERENCES groups(id), name TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS children_parent ON children(parent_id);
CREATE INDEX IF NOT EXISTS children_group ON children(group_id);
CREATE TABLE IF NOT EXISTS assignments(id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id), unit_id TEXT NOT NULL, title TEXT NOT NULL, activities TEXT NOT NULL, word_ids TEXT NOT NULL, due_date TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS assignments_group ON assignments(group_id);
CREATE TABLE IF NOT EXISTS reviews(child_id TEXT NOT NULL REFERENCES children(id), word_id TEXT NOT NULL, step INTEGER NOT NULL, due INTEGER NOT NULL, PRIMARY KEY(child_id,word_id));
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY, child_id TEXT NOT NULL REFERENCES children(id), assignment_id TEXT NOT NULL REFERENCES assignments(id), activity TEXT NOT NULL, word_id TEXT, correct INTEGER, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS attempts_child ON attempts(child_id,assignment_id);
CREATE TABLE IF NOT EXISTS completions(child_id TEXT NOT NULL REFERENCES children(id), assignment_id TEXT NOT NULL REFERENCES assignments(id), activity TEXT NOT NULL, completed_at INTEGER NOT NULL, PRIMARY KEY(child_id,assignment_id,activity));
CREATE TABLE IF NOT EXISTS login_limits(key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS student_claims(child_id TEXT PRIMARY KEY REFERENCES children(id), claim_hash TEXT UNIQUE NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS student_links(child_id TEXT PRIMARY KEY REFERENCES children(id),access_hash TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS student_sessions(session_hash TEXT PRIMARY KEY REFERENCES sessions(hash),child_id TEXT NOT NULL REFERENCES children(id),access_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reward_events(id TEXT PRIMARY KEY, child_id TEXT NOT NULL REFERENCES children(id), source TEXT NOT NULL, kind TEXT NOT NULL, label TEXT NOT NULL, xp INTEGER NOT NULL, created_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, UNIQUE(child_id,source));
CREATE INDEX IF NOT EXISTS reward_events_child ON reward_events(child_id,created_at);
CREATE TABLE IF NOT EXISTS class_meetings(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),day TEXT NOT NULL,time TEXT NOT NULL,duration INTEGER NOT NULL,UNIQUE(group_id,day,time));
CREATE INDEX IF NOT EXISTS class_meetings_day ON class_meetings(day);
CREATE TABLE IF NOT EXISTS attendance(meeting_id TEXT NOT NULL REFERENCES class_meetings(id),child_id TEXT NOT NULL REFERENCES children(id),status TEXT NOT NULL,PRIMARY KEY(meeting_id,child_id));
CREATE TABLE IF NOT EXISTS staff_accounts(id TEXT PRIMARY KEY,name TEXT NOT NULL,username TEXT UNIQUE NOT NULL,role TEXT NOT NULL,permissions TEXT NOT NULL,groups_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,salt TEXT NOT NULL DEFAULT '',password_hash TEXT NOT NULL DEFAULT '',invite_hash TEXT UNIQUE,invite_expires INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS campuses(id TEXT PRIMARY KEY,name TEXT NOT NULL);
INSERT INTO campuses(id,name) VALUES('main','Main campus') ON CONFLICT(id) DO NOTHING;
CREATE TABLE IF NOT EXISTS group_campuses(group_id TEXT PRIMARY KEY REFERENCES groups(id) ON DELETE CASCADE,campus_id TEXT NOT NULL REFERENCES campuses(id));
CREATE TABLE IF NOT EXISTS staff_campuses(staff_id TEXT PRIMARY KEY REFERENCES staff_accounts(id) ON DELETE CASCADE,campus_id TEXT NOT NULL REFERENCES campuses(id));

CREATE TABLE IF NOT EXISTS homework_time(id TEXT PRIMARY KEY,child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE,assignment_id TEXT NOT NULL REFERENCES assignments(id) ON DELETE CASCADE,assignment_version INTEGER NOT NULL,session_id TEXT NOT NULL,started_at INTEGER NOT NULL,ended_at INTEGER NOT NULL,CHECK(ended_at>started_at AND ended_at-started_at<=60000));
CREATE INDEX IF NOT EXISTS homework_time_report ON homework_time(child_id,assignment_id,assignment_version);

CREATE TABLE IF NOT EXISTS daily_practice_groups(group_id TEXT PRIMARY KEY REFERENCES groups(id) ON DELETE CASCADE,enabled INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS daily_runs(id TEXT PRIMARY KEY,child_id TEXT NOT NULL REFERENCES children(id) ON DELETE CASCADE,group_id TEXT NOT NULL REFERENCES groups(id) ON DELETE CASCADE,day TEXT NOT NULL,tasks TEXT NOT NULL,created_at INTEGER NOT NULL,finished_at INTEGER NOT NULL DEFAULT 0,UNIQUE(child_id,group_id,day));
CREATE TABLE IF NOT EXISTS daily_answers(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES daily_runs(id) ON DELETE CASCADE,task_id TEXT NOT NULL,correct INTEGER NOT NULL,created_at INTEGER NOT NULL,answer TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS daily_answers_run ON daily_answers(run_id);
